        "altPron": "dareuda vs. teullida · [dah-reu-dah vs teul-lee-dah]",
        "punchText": "“그건 틀린 게 아니라 서로 방식이 다른 것뿐이야.”",
        "def": "'다르다(차이)'와 '틀리다(오류)'의 구분. 일상 회화에서 한국인들도 자주 혼용하는 표현",
        "castDemis": "Demis",
        "castCraig": "크레이그 (Craig)",
        "castJennifer": "제니퍼 (Jennifer)",
        "ttsLang": "ko-KR"
